<?php
class Butchery extends Model
{
 protected $table='butchery_orders';
 public function pendingReceipts(){return$this->query("SELECT r.*,s.name supplier_name,t.transfer_number FROM butchery_receipts r LEFT JOIN suppliers s ON s.id=r.supplier_id LEFT JOIN livestock_transfers t ON t.id=r.livestock_transfer_id WHERE r.site_id=:site AND r.status='sanitary_pending'",['site'=>$this->viewSite()])->fetchAll();}
 public function pendingSlaughters(){return$this->query("SELECT s.*,l.lot_number FROM butchery_slaughters s JOIN butchery_live_lots l ON l.id=s.live_lot_id WHERE l.site_id=:site AND s.status='submitted'",['site'=>$this->viewSite()])->fetchAll();}
 public function dashboard(){ $this->expireLots();$site=$this->viewSite();return['items'=>$this->query("SELECT * FROM butchery_items WHERE status='active' AND deleted_at IS NULL ORDER BY item_kind,name")->fetchAll(),'suppliers'=>$this->query("SELECT id,name FROM suppliers WHERE status IN('active','validated') AND deleted_at IS NULL ORDER BY name")->fetchAll(),'incoming'=>$this->query("SELECT t.id,t.batch_id,t.source_unit,t.quantity_heads,t.quantity_kg,t.transfer_number,b.batch_number,sp.name species_name FROM livestock_transfers t JOIN livestock_batches b ON b.id=t.batch_id JOIN livestock_species sp ON sp.id=b.species_id WHERE t.destination_site_id=:site AND t.status='in_transit' AND t.deleted_at IS NULL AND NOT EXISTS(SELECT 1 FROM butchery_receipts r WHERE r.livestock_transfer_id=t.id)",['site'=>$site])->fetchAll(),'raw'=>$this->query("SELECT l.*,i.code item_code,i.name item_name,b.batch_number,s.name supplier_name FROM butchery_raw_lots l JOIN butchery_items i ON i.id=l.item_id LEFT JOIN livestock_batches b ON b.id=l.livestock_batch_id LEFT JOIN suppliers s ON s.id=l.supplier_id WHERE l.site_id=:site AND l.deleted_at IS NULL ORDER BY l.expiry_date",['site'=>$site])->fetchAll(),'live'=>$this->query("SELECT l.*,b.batch_number FROM butchery_live_lots l LEFT JOIN livestock_batches b ON b.id=l.livestock_batch_id WHERE l.site_id=:site ORDER BY l.id DESC",['site'=>$site])->fetchAll(),'recipes'=>$this->query("SELECT rv.id,r.code,r.name,rv.version_number FROM butchery_recipe_versions rv JOIN butchery_recipes r ON r.id=rv.recipe_id WHERE rv.status='active'")->fetchAll(),'orders'=>$this->query("SELECT o.*,r.code recipe_code,rv.version_number FROM butchery_orders o JOIN butchery_recipe_versions rv ON rv.id=o.recipe_version_id JOIN butchery_recipes r ON r.id=rv.recipe_id WHERE o.site_id=:site AND o.deleted_at IS NULL ORDER BY o.id DESC",['site'=>$site])->fetchAll(),'finished'=>$this->query("SELECT l.*,i.code item_code,i.name item_name,o.order_id FROM butchery_finished_lots l JOIN butchery_items i ON i.id=l.item_id JOIN butchery_order_outputs o ON o.id=l.order_output_id WHERE l.site_id=:site AND l.deleted_at IS NULL ORDER BY l.expiry_date",['site'=>$site])->fetchAll(),'transfers'=>$this->query("SELECT t.*,l.lot_number,i.name item_name FROM butchery_transfers t JOIN butchery_finished_lots l ON l.id=t.finished_lot_id JOIN butchery_items i ON i.id=l.item_id WHERE t.source_site_id=:site AND t.deleted_at IS NULL ORDER BY t.id DESC",['site'=>$site])->fetchAll()];}
 public function createReceipt(array$d,array$u){$site=$this->site();$source=$d['source_type'];$this->db->beginTransaction();try{$transfer=null;if($source==='internal_btr'){$transfer=$this->row("SELECT * FROM livestock_transfers WHERE id=? AND destination_site_id=? AND status='in_transit' FOR UPDATE",[$d['livestock_transfer_id'],$site]);if(!$transfer)throw new RuntimeException('BTR non réceptionnable ou déjà reçu.');$unit=$transfer['source_unit'];$heads=$transfer['quantity_heads'];$kg=$transfer['quantity_kg'];$supplier=null;$ref=$transfer['transfer_number'];}elseif($source==='external_bra'){$unit='kg';$heads=null;$kg=(float)$d['received_weight_kg'];$supplier=$d['supplier_id'];$ref=trim($d['source_reference']);if($kg<=0||!$supplier||$ref==='')throw new RuntimeException('Réception externe invalide.');}else throw new RuntimeException('Origine invalide.');$n='REC-BOUCH-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO butchery_receipts(site_id,source_type,livestock_transfer_id,supplier_id,receipt_number,source_reference,received_unit,received_heads,received_weight_kg,unit_cost,status,received_at,created_by) VALUES(:site,:source,:transfer,:supplier,:number,:ref,:unit,:heads,:kg,:cost,'sanitary_pending',:at,:user)",['site'=>$site,'source'=>$source,'transfer'=>$transfer['id']??null,'supplier'=>$supplier,'number'=>$n,'ref'=>$ref,'unit'=>$unit,'heads'=>$heads,'kg'=>$kg,'cost'=>(float)($d['unit_cost']??0),'at'=>$d['received_at'],'user'=>$u['id']]);$id=(int)$this->db->lastInsertId();if($source==='external_bra'){require_once dirname(__DIR__).'/services/DocumentService.php';(new DocumentService($this->db))->register('BRA',$site,'butchery_receipts',$id,'draft',$d['received_at'],$u);}$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function controlReceipt($id,array$d,array$u){$this->db->beginTransaction();try{$r=$this->row('SELECT * FROM butchery_receipts WHERE id=? FOR UPDATE',[$id]);if(!$r||$r['status']!=='sanitary_pending')throw new RuntimeException('Réception déjà contrôlée.');if((int)$r['created_by']===(int)$u['id']&&!Auth::canSelfValidate($u['id']))throw new RuntimeException('Le réceptionnaire ne peut pas valider le contrôle sanitaire.');Auth::requireSiteAccess($r['site_id']);$decision=$d['decision'];if($decision==='accept'&&($d['visual_status']!=='conform'||$d['document_status']!=='conform'))throw new RuntimeException('Un contrôle non conforme ne peut pas être accepté.');$this->query('INSERT INTO butchery_sanitary_controls(receipt_id,temperature_c,visual_status,document_status,decision,notes,controlled_at,controlled_by) VALUES(:receipt,:temp,:visual,:document,:decision,:notes,NOW(),:user)',['receipt'=>$id,'temp'=>$d['temperature_c']?:null,'visual'=>$d['visual_status'],'document'=>$d['document_status'],'decision'=>$decision,'notes'=>trim($d['notes']??'')?:null,'user'=>$u['id']]);if($decision==='reject'){$this->query("UPDATE butchery_receipts SET status='rejected',validated_by=:user WHERE id=:id",['user'=>$u['id'],'id'=>$id]);$this->db->commit();return null;}$item=$this->row("SELECT * FROM butchery_items WHERE id=? AND item_kind IN('raw_material','additive') AND status='active'",[$d['item_id']]);if(!$item)throw new RuntimeException('Matière boucherie invalide.');$lot='MPB-'.date('YmdHis').'-'.random_int(100,999);$expiry=$d['expiry_date'];if($expiry<date('Y-m-d'))throw new RuntimeException('DLC déjà dépassée.');if($r['received_unit']==='head'){$transfer=$this->row('SELECT * FROM livestock_transfers WHERE id=?',[$r['livestock_transfer_id']]);$this->query("INSERT INTO butchery_live_lots(site_id,receipt_id,livestock_batch_id,lot_number,available_heads,status,received_at) VALUES(:site,:receipt,:batch,:lot,:heads,'available',:at)",['site'=>$r['site_id'],'receipt'=>$id,'batch'=>$transfer['batch_id'],'lot'=>$lot,'heads'=>$r['received_heads'],'at'=>$r['received_at']]);}else{$batch=null;if($r['livestock_transfer_id'])$batch=$this->query('SELECT batch_id FROM livestock_transfers WHERE id=:id',['id'=>$r['livestock_transfer_id']])->fetchColumn();$this->query("INSERT INTO butchery_raw_lots(site_id,item_id,receipt_id,livestock_batch_id,supplier_id,lot_number,production_date,expiry_date,quantity_kg,reserved_kg,unit_cost,status) VALUES(:site,:item,:receipt,:batch,:supplier,:lot,:production,:expiry,:qty,0,:cost,'available')",['site'=>$r['site_id'],'item'=>$item['id'],'receipt'=>$id,'batch'=>$batch?:null,'supplier'=>$r['supplier_id'],'lot'=>$lot,'production'=>$d['production_date'],'expiry'=>$expiry,'qty'=>$r['received_weight_kg'],'cost'=>$r['unit_cost']]);$raw=(int)$this->db->lastInsertId();$this->rawMove($raw,'receipt_in',$r['received_weight_kg'],0,$r['received_weight_kg'],'butchery_receipts',$id,$u);}$this->query("UPDATE butchery_receipts SET status='accepted',validated_by=:user WHERE id=:id",['user'=>$u['id'],'id'=>$id]);if($r['livestock_transfer_id'])$this->query("UPDATE livestock_transfers SET status='received',received_at=NOW() WHERE id=:id",['id'=>$r['livestock_transfer_id']]);$this->logActivity('sanitary_receipt','butchery','butchery_receipts',$id,'Contrôle sanitaire et création du lot source.',null,['decision'=>$decision,'lot'=>$lot],$u);$this->db->commit();return$lot;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createSlaughter(array$d,array$u){$site=$this->site();$live=$this->row("SELECT * FROM butchery_live_lots WHERE id=? AND site_id=? AND status IN('available','partially_slaughtered')",[$d['live_lot_id'],$site]);$heads=(int)$d['input_heads'];$net=(float)$d['gross_weight_kg']-(float)$d['tare_weight_kg'];if(!$live||$heads<=0||$heads>(int)$live['available_heads']||$net<=0)throw new RuntimeException('Abattage/pesée invalide.');$n='ABAT-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO butchery_slaughters(live_lot_id,raw_item_id,slaughter_number,input_heads,gross_weight_kg,tare_weight_kg,net_weight_kg,status,slaughtered_at,created_by) VALUES(:live,:item,:number,:heads,:gross,:tare,:net,'submitted',:at,:user)",['live'=>$live['id'],'item'=>$d['raw_item_id'],'number'=>$n,'heads'=>$heads,'gross'=>$d['gross_weight_kg'],'tare'=>$d['tare_weight_kg'],'net'=>$net,'at'=>$d['slaughtered_at'],'user'=>$u['id']]);return(int)$this->db->lastInsertId();}
 public function validateSlaughter($id,array$d,array$u){$this->db->beginTransaction();try{$s=$this->row('SELECT s.*,l.site_id,l.available_heads,l.livestock_batch_id,l.receipt_id FROM butchery_slaughters s JOIN butchery_live_lots l ON l.id=s.live_lot_id WHERE s.id=? FOR UPDATE',[$id]);if(!$s||$s['status']!=='submitted')throw new RuntimeException('Abattage non validable.');if((int)$s['created_by']===(int)$u['id']&&!Auth::canSelfValidate($u['id']))throw new RuntimeException('Le créateur ne peut pas valider l’abattage.');Auth::requireSiteAccess($s['site_id']);if((int)$s['available_heads']<(int)$s['input_heads'])throw new RuntimeException('Effectif réceptionné insuffisant.');$remain=(int)$s['available_heads']-(int)$s['input_heads'];$this->query("UPDATE butchery_live_lots SET available_heads=:heads,status=IF(:heads2>0,'partially_slaughtered','depleted') WHERE id=:id",['heads'=>$remain,'heads2'=>$remain,'id'=>$s['live_lot_id']]);$expiry=$d['expiry_date'];if($expiry<date('Y-m-d'))throw new RuntimeException('DLC invalide.');$lot='MPB-AB-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO butchery_raw_lots(site_id,item_id,slaughter_id,livestock_batch_id,lot_number,production_date,expiry_date,quantity_kg,reserved_kg,unit_cost,status) VALUES(:site,:item,:slaughter,:batch,:lot,:production,:expiry,:qty,0,:cost,'available')",['site'=>$s['site_id'],'item'=>$s['raw_item_id'],'slaughter'=>$id,'batch'=>$s['livestock_batch_id'],'lot'=>$lot,'production'=>substr($s['slaughtered_at'],0,10),'expiry'=>$expiry,'qty'=>$s['net_weight_kg'],'cost'=>(float)$d['unit_cost']]);$raw=(int)$this->db->lastInsertId();$this->rawMove($raw,'slaughter_in',$s['net_weight_kg'],0,$s['net_weight_kg'],'butchery_slaughters',$id,$u);$this->query("UPDATE butchery_slaughters SET status='validated',validated_by=:user,validated_at=NOW() WHERE id=:id",['user'=>$u['id'],'id'=>$id]);$this->db->commit();return$raw;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createRecipe(array$d,array$u){$this->db->beginTransaction();try{$r=$this->row('SELECT * FROM butchery_recipes WHERE code=? FOR UPDATE',[trim($d['code'])]);if(!$r){$this->query("INSERT INTO butchery_recipes(code,name,status,created_by) VALUES(:code,:name,'active',:user)",['code'=>trim($d['code']),'name'=>trim($d['name']),'user'=>$u['id']]);$r=['id'=>$this->db->lastInsertId()];}$v=(int)$this->query('SELECT COALESCE(MAX(version_number),0)+1 FROM butchery_recipe_versions WHERE recipe_id=:id FOR UPDATE',['id'=>$r['id']])->fetchColumn();$this->query("UPDATE butchery_recipe_versions SET status='retired' WHERE recipe_id=:id",['id'=>$r['id']]);$this->query("INSERT INTO butchery_recipe_versions(recipe_id,version_number,status,effective_from,created_by) VALUES(:recipe,:version,'active',CURDATE(),:user)",['recipe'=>$r['id'],'version'=>$v,'user'=>$u['id']]);$id=(int)$this->db->lastInsertId();$this->query("INSERT INTO butchery_recipe_components(recipe_version_id,item_id,component_type,percentage) VALUES(:version,:item,'raw_material',100)",['version'=>$id,'item'=>$d['raw_item_id']]);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createOrder(array$d,array$u){$site=$this->site();$this->expireLots();$raw=$this->lockRaw($d['raw_lot_id']);$qty=(float)$d['planned_input_kg'];if($qty<=0||$qty>((float)$raw['quantity_kg']-(float)$raw['reserved_kg']))throw new RuntimeException('Matière disponible insuffisante.');$rv=$this->row("SELECT * FROM butchery_recipe_versions WHERE id=? AND status='active'",[$d['recipe_version_id']]);if(!$rv)throw new RuntimeException('Recette inactive.');$n='OF-BOUCH-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO butchery_orders(site_id,recipe_version_id,order_number,planned_input_kg,production_date,status,created_by) VALUES(:site,:recipe,:number,:qty,:date,'in_progress',:user)",['site'=>$site,'recipe'=>$rv['id'],'number'=>$n,'qty'=>$qty,'date'=>$d['production_date'],'user'=>$u['id']]);return(int)$this->db->lastInsertId();}
 public function submitOrder($id,array$d,array$u){$this->db->beginTransaction();try{$o=$this->row('SELECT * FROM butchery_orders WHERE id=? FOR UPDATE',[$id]);if(!$o||$o['status']!=='in_progress')throw new RuntimeException('OF non saisissable.');Auth::requireSiteAccess($o['site_id']);$raw=$this->lockRaw($d['raw_lot_id']);$rq=(float)$d['raw_quantity_kg'];$aq=(float)($d['additive_quantity_kg']??0);$out=(float)$d['output_kg'];$co=(float)$d['co_product_kg'];$loss=$rq+$aq-$out-$co;if($rq<=0||$out<0||$co<0||$loss<0||$rq>(float)$raw['quantity_kg'])throw new RuntimeException('Résultats ou stocks incohérents.');$this->query("INSERT INTO butchery_order_consumptions(order_id,raw_lot_id,item_id,consumption_type,quantity_kg,unit_cost) VALUES(:order,:lot,:item,'raw_material',:qty,:cost)",['order'=>$id,'lot'=>$raw['id'],'item'=>$raw['item_id'],'qty'=>$rq,'cost'=>$raw['unit_cost']]);if($aq>0)$this->query("INSERT INTO butchery_order_consumptions(order_id,raw_lot_id,item_id,consumption_type,quantity_kg,unit_cost) VALUES(:order,NULL,:item,'additive',:qty,:cost)",['order'=>$id,'item'=>$d['additive_item_id'],'qty'=>$aq,'cost'=>(float)$d['additive_unit_cost']]);$this->query("INSERT INTO butchery_order_outputs(order_id,item_id,output_type,quantity_kg,expiry_date) VALUES(:order,:item,'finished_product',:qty,:expiry)",['order'=>$id,'item'=>$d['finished_item_id'],'qty'=>$out,'expiry'=>$d['expiry_date']]);if($co>0)$this->query("INSERT INTO butchery_order_outputs(order_id,item_id,output_type,quantity_kg,expiry_date) VALUES(:order,:item,'co_product',:qty,:expiry)",['order'=>$id,'item'=>$d['co_product_item_id'],'qty'=>$co,'expiry'=>$d['co_product_expiry_date']]);$input=$rq+$aq;$yield=$input>0?($out+$co)/$input*100:0;$this->query("UPDATE butchery_orders SET actual_input_kg=:input,output_kg=:out,co_product_kg=:co,loss_kg=:loss,yield_percent=:yield,labor_cost=:labor,energy_cost=:energy,allocated_cost=:allocated,status='results_submitted' WHERE id=:id",['input'=>$input,'out'=>$out,'co'=>$co,'loss'=>$loss,'yield'=>$yield,'labor'=>(float)$d['labor_cost'],'energy'=>(float)$d['energy_cost'],'allocated'=>(float)$d['allocated_cost'],'id'=>$id]);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function validateOrder($id,array$u){$this->db->beginTransaction();try{$o=$this->row('SELECT * FROM butchery_orders WHERE id=? FOR UPDATE',[$id]);if(!$o||$o['status']!=='results_submitted')throw new RuntimeException('OF non validable ou déjà validé.');if((int)$o['created_by']===(int)$u['id']&&!Auth::canSelfValidate($u['id']))throw new RuntimeException('Le créateur ne peut pas valider l’OF.');Auth::requireSiteAccess($o['site_id']);$cs=$this->query('SELECT * FROM butchery_order_consumptions WHERE order_id=:id FOR UPDATE',['id'=>$id])->fetchAll();$material=0;foreach($cs as$c){$material+=(float)$c['quantity_kg']*(float)$c['unit_cost'];if($c['raw_lot_id']){$l=$this->lockRaw($c['raw_lot_id']);if((float)$l['quantity_kg']<(float)$c['quantity_kg'])throw new RuntimeException('Consommation supérieure au disponible.');$after=(float)$l['quantity_kg']-(float)$c['quantity_kg'];$this->query("UPDATE butchery_raw_lots SET quantity_kg=:q,status=IF(:q2>0,'available','depleted') WHERE id=:id",['q'=>$after,'q2'=>$after,'id'=>$l['id']]);$this->rawMove($l['id'],'production_out',$c['quantity_kg'],$l['quantity_kg'],$after,'butchery_orders',$id,$u);}}$total=$material+(float)$o['labor_cost']+(float)$o['energy_cost']+(float)$o['allocated_cost'];$outputs=$this->query('SELECT * FROM butchery_order_outputs WHERE order_id=:id FOR UPDATE',['id'=>$id])->fetchAll();$basis=(float)$o['output_kg']+(float)$o['co_product_kg'];foreach($outputs as$out){$cost=$basis>0?$total*((float)$out['quantity_kg']/$basis):0;$lot='PFB-'.date('YmdHis').'-'.$out['id'];$this->query("INSERT INTO butchery_finished_lots(site_id,item_id,order_output_id,lot_number,production_date,expiry_date,quantity_kg,reserved_kg,unit_cost,status) VALUES(:site,:item,:output,:lot,:production,:expiry,:qty,0,:cost,'available')",['site'=>$o['site_id'],'item'=>$out['item_id'],'output'=>$out['id'],'lot'=>$lot,'production'=>$o['production_date'],'expiry'=>$out['expiry_date'],'qty'=>$out['quantity_kg'],'cost'=>(float)$out['quantity_kg']>0?$cost/(float)$out['quantity_kg']:0]);$finished=(int)$this->db->lastInsertId();$this->finishedMove($finished,'production_in',$out['quantity_kg'],0,$out['quantity_kg'],'butchery_orders',$id,$u);}$this->query("UPDATE butchery_orders SET status='validated',validated_by=:user,validated_at=NOW(),total_cost=:total,cost_per_kg=:unit WHERE id=:id",['user'=>$u['id'],'total'=>$total,'unit'=>$basis>0?$total/$basis:0,'id'=>$id]);$this->logActivity('validate_butchery_order','butchery','butchery_orders',$id,'Consommations, coûts et sorties validés atomiquement.',null,['total_cost'=>$total],$u);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function sell(array$d,array$u){$this->expireLots();$site=$this->site();$type=$d['lot_type'];$this->db->beginTransaction();try{if($type==='raw'){$l=$this->lockRaw($d['lot_id']);$table='butchery_raw_lots';$field='raw_lot_id';$move='direct_sale_out';}else{$l=$this->lockFinished($d['lot_id']);$table='butchery_finished_lots';$field='finished_lot_id';$move='sale_out';}$q=(float)$d['quantity_kg'];if($q<=0||$q>(float)$l['quantity_kg'])throw new RuntimeException('Stock vendable insuffisant.');$n='VBOU-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO butchery_sales(site_id,sale_number,{$field},customer_name,quantity_kg,unit_price,sold_at,status,created_by) VALUES(:site,:number,:lot,:customer,:qty,:price,NOW(),'validated',:user)",['site'=>$site,'number'=>$n,'lot'=>$l['id'],'customer'=>trim($d['customer_name']),'qty'=>$q,'price'=>(float)$d['unit_price'],'user'=>$u['id']]);$sale=(int)$this->db->lastInsertId();$after=(float)$l['quantity_kg']-$q;$this->query("UPDATE {$table} SET quantity_kg=:q,status=IF(:q2>0,'available','depleted') WHERE id=:id",['q'=>$after,'q2'=>$after,'id'=>$l['id']]);if($type==='raw')$this->rawMove($l['id'],$move,$q,$l['quantity_kg'],$after,'butchery_sales',$sale,$u);else$this->finishedMove($l['id'],$move,$q,$l['quantity_kg'],$after,'butchery_sales',$sale,$u);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createTransfer(array$d,array$u){$site=$this->site();$dest=(int)$this->query("SELECT id FROM sites WHERE code='DEP-DEC'")->fetchColumn();$this->expireLots();$l=$this->lockFinished($d['finished_lot_id']);$q=(float)$d['quantity_kg'];if($q<=0||$q>((float)$l['quantity_kg']-(float)$l['reserved_kg']))throw new RuntimeException('Stock fini disponible insuffisant.');$n='BTR-BOUCH-'.date('YmdHis').'-'.random_int(100,999);$this->db->beginTransaction();try{$this->query("INSERT INTO butchery_transfers(finished_lot_id,source_site_id,destination_site_id,transfer_number,quantity_kg,status,created_by) VALUES(:lot,:source,:dest,:number,:qty,'draft',:user)",['lot'=>$l['id'],'source'=>$site,'dest'=>$dest,'number'=>$n,'qty'=>$q,'user'=>$u['id']]);$id=(int)$this->db->lastInsertId();require_once dirname(__DIR__).'/services/DocumentService.php';(new DocumentService($this->db))->register('BTR',$site,'butchery_transfers',$id,'draft',date('Y-m-d H:i:s'),$u);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function approveTransfer($id,array$u){$this->db->beginTransaction();try{$t=$this->row('SELECT * FROM butchery_transfers WHERE id=? FOR UPDATE',[$id]);if(!$t||$t['status']!=='draft')throw new RuntimeException('BTR non validable.');if((int)$t['created_by']===(int)$u['id']&&!Auth::canSelfValidate($u['id']))throw new RuntimeException('Le créateur ne peut pas valider le BTR.');$l=$this->lockFinished($t['finished_lot_id']);$available=(float)$l['quantity_kg']-(float)$l['reserved_kg'];if($available<(float)$t['quantity_kg'])throw new RuntimeException('Stock fini insuffisant.');$after=(float)$l['reserved_kg']+(float)$t['quantity_kg'];$this->query("UPDATE butchery_finished_lots SET reserved_kg=:q,status='reserved' WHERE id=:id",['q'=>$after,'id'=>$l['id']]);$this->finishedMove($l['id'],'reserve',$t['quantity_kg'],$l['quantity_kg'],$l['quantity_kg'],'butchery_transfers',$id,$u);$this->query("UPDATE butchery_transfers SET status='approved',approved_by=:user WHERE id=:id",['user'=>$u['id'],'id'=>$id]);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function dispatchTransfer($id,array$u){$this->db->beginTransaction();try{$t=$this->row('SELECT * FROM butchery_transfers WHERE id=? FOR UPDATE',[$id]);if(!$t||$t['status']!=='approved')throw new RuntimeException('BTR non expédiable ou déjà expédié.');$l=$this->row('SELECT * FROM butchery_finished_lots WHERE id=? FOR UPDATE',[$t['finished_lot_id']]);$q=(float)$t['quantity_kg'];if((float)$l['quantity_kg']<$q||(float)$l['reserved_kg']<$q||$l['expiry_date']<date('Y-m-d'))throw new RuntimeException('Stock réservé invalide ou expiré.');$after=(float)$l['quantity_kg']-$q;$reserved=(float)$l['reserved_kg']-$q;$this->query("UPDATE butchery_finished_lots SET quantity_kg=:q,reserved_kg=:r,status=IF(:q2>0,'available','in_transit') WHERE id=:id",['q'=>$after,'r'=>$reserved,'q2'=>$after,'id'=>$l['id']]);$this->finishedMove($l['id'],'transfer_out',$q,$l['quantity_kg'],$after,'butchery_transfers',$id,$u);$this->query("UPDATE butchery_transfers SET status='in_transit',dispatched_at=NOW() WHERE id=:id",['id'=>$id]);$this->logActivity('dispatch_butchery_transfer','butchery','butchery_transfers',$id,'Transfert produit boucherie vers DECO.',null,$t,$u);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function expireLots(){$this->query("UPDATE butchery_raw_lots SET status='expired' WHERE expiry_date<CURDATE() AND status IN('available','reserved')");$this->query("UPDATE butchery_finished_lots SET status='expired' WHERE expiry_date<CURDATE() AND status IN('available','reserved')");}
 public function hasOperationalSiteContext(){$s=Auth::currentSiteId();if($s===null)return false;return$this->query('SELECT code FROM sites WHERE id=:id AND status=\'active\' AND deleted_at IS NULL',['id'=>$s])->fetchColumn()==='BOUCH';}
 private function viewSite(){$s=(int)$this->query("SELECT id FROM sites WHERE code='BOUCH' AND status='active' AND deleted_at IS NULL LIMIT 1")->fetchColumn();if(!$s)throw new RuntimeException('Site Boucherie introuvable.');if(Auth::canViewConsolidated()||Auth::canAccessSite($s))return$s;http_response_code(403);throw new RuntimeException('Accès refusé au site Boucherie.');}private function site(){$s=Auth::requireCurrentSite();if($this->query('SELECT code FROM sites WHERE id=:id',['id'=>$s])->fetchColumn()!=='BOUCH')throw new RuntimeException('Sélectionnez le site Boucherie.');return$s;}private function lockRaw($id){$l=$this->row('SELECT * FROM butchery_raw_lots WHERE id=? FOR UPDATE',[$id]);if(!$l||$l['site_id']!=$this->site()||$l['status']!=='available'||$l['expiry_date']<date('Y-m-d'))throw new RuntimeException('Lot matière indisponible ou expiré.');return$l;}private function lockFinished($id){$l=$this->row('SELECT * FROM butchery_finished_lots WHERE id=? FOR UPDATE',[$id]);if(!$l||$l['site_id']!=$this->site()||$l['status']!=='available'||$l['expiry_date']<date('Y-m-d'))throw new RuntimeException('Lot fini indisponible ou expiré.');return$l;}private function rawMove($l,$t,$q,$b,$a,$rt,$rid,$u){$this->query('INSERT INTO butchery_raw_movements(raw_lot_id,movement_type,quantity_kg,stock_before_kg,stock_after_kg,reference_type,reference_id,created_by) VALUES(:l,:t,:q,:b,:a,:rt,:rid,:u)',['l'=>$l,'t'=>$t,'q'=>$q,'b'=>$b,'a'=>$a,'rt'=>$rt,'rid'=>$rid,'u'=>$u['id']]);}private function finishedMove($l,$t,$q,$b,$a,$rt,$rid,$u){$this->query('INSERT INTO butchery_finished_movements(finished_lot_id,movement_type,quantity_kg,stock_before_kg,stock_after_kg,reference_type,reference_id,created_by) VALUES(:l,:t,:q,:b,:a,:rt,:rid,:u)',['l'=>$l,'t'=>$t,'q'=>$q,'b'=>$b,'a'=>$a,'rt'=>$rt,'rid'=>$rid,'u'=>$u['id']]);}private function row($s,$p=[]){$q=$this->db->prepare($s);$q->execute($p);return$q->fetch();}
}
